def equivalent(req, got, exp, ben_of):
    """ben_of(flow_id)->benefit; returns None if ok else reason"""
    if 'infeasible' in exp:
        return None if got == {'infeasible': True} else 'expected infeasible, got %r' % (got,)
    if 'infeasible' in got:
        return 'unexpected infeasible'
    caps = req['capacities']; flows = {f['id']: f for f in req['flows']}
    pinned = set(req['pinned'])
    sel = got['selected']
    if sel != sorted(set(sel)):
        return 'not sorted/distinct'
    if not pinned <= set(sel):
        return 'pinned missing'
    use = {}
    for fid in sel:
        for n in flows[fid]['path']:
            use[n] = use.get(n, 0) + 1
    for n, u in use.items():
        if u > caps[n]:
            return 'capacity violated at %s' % n
    saved = sum(ben_of[f] for f in sel)
    if saved != got['saved']:
        return 'saved mismatch %d vs %d' % (saved, got['saved'])
    if (saved, -len(sel)) != (exp['saved'], -len(exp['selected'])):
        return 'suboptimal: got (%d,%d) exp (%d,%d)' % (saved, -len(sel), exp['saved'], -len(exp['selected']))
    return None
EOF
